<?php
namespace App\Http\Controllers;
use App\Models\Asset; use App\Models\WorkLog; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Illuminate\View\View;
class AssetWorkController extends Controller {
 public function show(Request $request,Asset $asset):View{$active=WorkLog::with(['team','author'])->where('asset_id',$asset->id)->where('created_by',$request->user()->id)->where('status','in_progress')->latest('started_at')->first();return view('operator.asset',['asset'=>$asset->load('location'),'active'=>$active,'types'=>WorkLog::TYPES]);}
 public function start(Request $request,Asset $asset):RedirectResponse{$data=$request->validate(['work_type'=>['required',Rule::in(array_keys(WorkLog::TYPES))],'title'=>['nullable','string','max:255'],'description'=>['nullable','string','max:5000']]);$team=$request->user()->workTeams()->where('work_teams.active',true)->first();if(!$team&&$request->user()->isSupervisor())$team=\App\Models\WorkTeam::where('active',true)->first();abort_unless($team,422,'El usuario no tiene un equipo de trabajo asignado.');$exists=WorkLog::where('created_by',$request->user()->id)->where('asset_id',$asset->id)->where('status','in_progress')->exists();abort_if($exists,422,'Ya tienes una tarea activa sobre este equipo.');WorkLog::create(['number'=>'BIT-'.now()->format('Ymd').'-'.Str::upper(Str::random(6)),'created_by'=>$request->user()->id,'work_team_id'=>$team->id,'location_id'=>$asset->location_id,'asset_id'=>$asset->id,'title'=>$data['title']??null,'work_type'=>$data['work_type'],'priority'=>'normal','status'=>'in_progress','description'=>$data['description']??null,'started_at'=>now()]);return back()->with('success','Tarea iniciada. El horario fue registrado automáticamente.');}
 public function finish(Request $request,Asset $asset,WorkLog $workLog):RedirectResponse{abort_unless($workLog->asset_id===$asset->id&&($workLog->created_by===$request->user()->id||$request->user()->isSupervisor()),403);abort_unless($workLog->status==='in_progress',422);$data=$request->validate(['title'=>['nullable','string','max:255'],'description'=>['nullable','string','max:5000'],'result'=>['nullable','string','max:5000'],'observations'=>['nullable','string','max:5000'],'priority'=>['nullable',Rule::in(array_keys(WorkLog::PRIORITIES))],'next_action_at'=>['nullable','date']]);$workLog->update($data+['status'=>'completed','finished_at'=>now(),'closed_by'=>$request->user()->id]);return redirect()->route('logbook.show',$workLog)->with('success','Tarea finalizada. El horario de cierre fue registrado automáticamente.');}
}
